"""Generate maximum-scale requests for timing."""
import json, random, sys

def host_routes(n, base=1, hop0=0):
    return [["%032x" % (base+i), ] for i in range(n)]

def pfx(value, length):
    v = value >> (128-length) << (128-length) if length else 0
    return '%x::/%d' % (v >> 112, length) if length <= 16 else '%032x/%d' % (v, length)

def addr_text(value):
    return ':'.join('%x' % ((value >> (16*(7-i))) & 0xffff) for i in range(8))

def make_case(runs_list, nroutes_extra=0, nbursts=64, naddr=64, cap=12, seed=0):
    """runs_list: desired R per version (v0..v7)."""
    rng = random.Random(seed)
    initial = [["::/0", 0]]
    # v0 runs = R: host routes at 1..R-2 with distinct hops -> starts 0..R-1
    R0 = runs_list[0]
    for i in range(R0-1):
        initial.append([addr_text(i+1)+"/128", (i % 2147483646) + 1])
    # extra covered routes that never change forwarding
    for i in range(nroutes_extra):
        initial.append([addr_text(1)+"/128", 1]) if False else None
    txs = []
    for v in range(1, len(runs_list)):
        target = runs_list[v]
        tx = []
        if target == 1:
            for i in range(R0-1):
                tx.append(["erase", addr_text(i+1)+"/128"])
            R0 = 1
        txs.append(tx)
    bursts = []
    for b in range(nbursts):
        v = rng.randrange(len(runs_list))
        addrs = [addr_text(rng.randrange(0, 1<<128)) for _ in range(naddr)]
        bursts.append({"version": v, "repeat": rng.randrange(1, 1000001), "addresses": addrs})
    return {"initial": initial, "transactions": txs, "bursts": bursts,
            "cache_pages": cap,
            "costs": {"hit": rng.randrange(1,17), "miss": rng.randrange(17,257),
                      "decode": [rng.randrange(0,17) for _ in range(3)]}}

if __name__ == "__main__":
    kind = sys.argv[1] if len(sys.argv)>1 else "big"
    if kind == "big":
        # two heavy versions, 32 versions total, sum R = 128
        c1 = make_case([64]+[1]*7, nbursts=64, naddr=64, seed=1)
        c2 = make_case([34]+[1]*7, nbursts=64, naddr=64, seed=2)
        c3 = make_case([8]*8, nbursts=32, naddr=32, seed=3)
        c4 = make_case([4]*8, nbursts=32, naddr=32, seed=4)
        req = {"cases":[c1,c2,c3,c4]}
    elif kind == "wide":
        req = {"cases":[make_case([16]*8, nbursts=64, naddr=64, seed=i) for i in range(4)]}
    print(json.dumps(req))
